// Traza INVENTADA (no son datos reales): pedidos por segundo cada 10 minutos durante 24 h
const pasos = 144;
const carga = [];
for (let i = 0; i < pasos; i++) {
  const h = i / 6;
  let r = 120 + 80 * Math.exp(-((h - 8) ** 2) / 4) + 520 * Math.exp(-((h - 20) ** 2) / 3);
  if (i === 60) r += 300; // pico corto e inesperado a las 10:00
  carga.push(Math.round(r));
}
const CAP = 100;        // pedidos/s que aguanta una instancia (inventado)
const PRECIO = 0.10;    // USD por instancia-hora (INVENTADO)
const ARRANQUE = 1;     // pasos de 10 min hasta que una instancia nueva sirve
function simular(politica) {
  let activas = politica.inicial, pendientes = [], perdidos = 0, total = 0, instHoras = 0, maxAct = 0;
  for (let i = 0; i < pasos; i++) {
    activas += pendientes.filter(p => p === i).length;
    pendientes = pendientes.filter(p => p > i);
    const r = carga[i];
    const sirve = Math.min(r, activas * CAP);
    perdidos += (r - sirve) * 600; total += r * 600;
    instHoras += (activas + pendientes.length) / 6;
    maxAct = Math.max(maxAct, activas);
    if (politica.auto) {
      const deseadas = Math.min(politica.max, Math.max(politica.min, Math.ceil(r / (CAP * politica.objetivo))));
      const enCamino = activas + pendientes.length;
      if (deseadas > enCamino) for (let k = 0; k < deseadas - enCamino; k++) pendientes.push(i + ARRANQUE);
      else if (deseadas < activas && i % 3 === 0) activas = Math.max(deseadas, activas - 2); // baja con calma
    }
  }
  return { perdidoPct: (100 * perdidos / total).toFixed(2), costo: (instHoras * PRECIO).toFixed(2), instHoras: instHoras.toFixed(1), maxAct };
}
const pico = Math.max(...carga), prom = carga.reduce((a, b) => a + b) / pasos;
console.log('pico', pico, 'req/s; promedio', prom.toFixed(0), 'req/s');
console.log('fija para el promedio  ', JSON.stringify(simular({ inicial: Math.ceil(prom / CAP) })));
console.log('fija para el pico      ', JSON.stringify(simular({ inicial: Math.ceil(pico / CAP / 0.6) })));
console.log('autoscaling objetivo 60%', JSON.stringify(simular({ auto: true, inicial: 2, min: 2, max: 20, objetivo: 0.6 })));
console.log('autoscaling objetivo 90%', JSON.stringify(simular({ auto: true, inicial: 2, min: 2, max: 20, objetivo: 0.9 })));
